1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.function.common.FiscalYear;
11	import org.springframework.samples.petclinic.rest.function.common.Localities;
12	import org.springframework.samples.petclinic.rest.function.common.MemberId;
13	
14	/**
15	 * Assigns the {@code memberId} to a newly built owner, formatted
16	 * {@code <REGION><FY><HASH8><CHK>} (no separators) where {@code REGION} is the region code
17	 * derived from the owner's postcode (see {@link Localities#locality(String, String)}),
18	 * {@code FY} is the two-digit fiscal year of the owner's registration date, {@code HASH8} is
19	 * the first 8 upper-case hex characters of the SHA-256 digest over the owner's normalized
20	 * telephone (E.164, see {@link OwnerTelephone}) concatenated with its last name, and
21	 * {@code CHK} is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}
22	 * (e.g. {@code NSW271A2B3C4D5}).
23	 *
24	 * <p>This is a stable identity: the region-and-hash value carries no sequence number, so it
25	 * does not depend on how many owners already exist. When that value collides with an existing
26	 * owner's {@code memberId}, {@code -<n>} is appended with the smallest {@code n} of 2 or more
27	 * that makes it unique, so distinct owners always get distinct memberIds. Every value built
28	 * from the memberId — the fiscal-year label, the create audit line and the derived locality —
29	 * follows from this identity. Mutates the owner in place (the same object {@link SaveOwner}
30	 * persists).
31	 */
32	public class AssignOwnerMemberId {
33	
34	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
35	        String region = Localities.locality(owner.getCity(), owner.getPostcode());
36	        String telephone = OwnerTelephone.canonical(owner.getTelephone());
37	        String fiscalYear = FiscalYear.twoDigit(owner.getRegistrationDate());
38	        String base = MemberId.base(region, fiscalYear, telephone, owner.getLastName());
39	
40	        Set<String> taken = ownerRepository.findAll().stream()
41	                .filter(existing -> existing.getId() == null
42	                        || !existing.getId().equals(owner.getId()))
43	                .map(Owner::getMemberId)
44	                .filter(memberId -> memberId != null)
45	                .collect(Collectors.toCollection(HashSet::new));
46	
47	        String memberId = base;
48	        for (int n = 2; taken.contains(memberId); n++) {
49	            memberId = base + "-" + n;
50	        }
51	        owner.setMemberId(memberId);
52	    }
53	}
