3	import java.util.Set;
4	import java.util.regex.Pattern;
5	import java.util.stream.Collectors;
6	
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Normalization for the optional owner {@code email}: when present it must be a syntactically
11	 * valid address whose domain is not on the disposable-domain blocklist; it is stored and returned
12	 * lower-cased. An absent (null/blank) email is left untouched. A syntactically invalid value
13	 * raises {@link InvalidOwnerEmailException}; a blocklisted domain raises
14	 * {@link DisposableOwnerEmailException}; both make the endpoint respond 400.
15	 */
16	final class OwnerEmail {
17	
18	    /** A pragmatic address check: one {@code @}, non-empty local and domain parts, a dotted domain. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
20	
21	    /** Disposable email domains rejected outright. */
22	    private static final Set<String> BLOCKED_DOMAINS =
23	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
24	
25	    /** The second-level labels of the blocked domains (e.g. {@code mailinator}). */
26	    private static final Set<String> BLOCKED_LABELS = BLOCKED_DOMAINS.stream()
27	            .map(OwnerEmail::secondLevelLabel).collect(Collectors.toUnmodifiableSet());
28	
29	    private OwnerEmail() {
30	    }
31	
32	    /**
33	     * If the request carries a non-blank email, validate and lower-case it in place; otherwise leave
34	     * it as-is.
35	     */
36	    static void normalize(OwnerFieldsDto request)
37	            throws InvalidOwnerEmailException, DisposableOwnerEmailException {
38	        String email = request.getEmail();
39	        if (email == null || email.isBlank()) {
40	            return;
41	        }
42	        if (!EMAIL.matcher(email).matches()) {
43	            throw new InvalidOwnerEmailException(email);
44	        }
45	        String normalized = email.toLowerCase();
46	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
47	        if (BLOCKED_DOMAINS.contains(domain)) {
48	            throw new DisposableOwnerEmailException(email);
49	        }
50	        request.setEmail(normalized);
51	    }
52	
53	    /**
54	     * Whether the given email's domain is <em>disposable-adjacent</em>: a near-variant of a
55	     * blocklisted disposable domain that dodges the exact-match rejection in {@link #normalize}.
56	     * It is adjacent when its second-level label equals a blocked domain's — whether under a
57	     * different public suffix ({@code mailinator.net}) or as a subdomain ({@code x.mailinator.com}).
58	     * A null, blank or address-less value, or one whose domain matches no blocked label, is not
59	     * adjacent.
60	     */
61	    static boolean isDisposableAdjacent(String email) {
62	        if (email == null || email.isBlank()) {
63	            return false;
64	        }
65	        int at = email.lastIndexOf('@');
66	        if (at < 0 || at == email.length() - 1) {
67	            return false;
68	        }
69	        String domain = email.substring(at + 1).toLowerCase();
70	        return BLOCKED_LABELS.contains(secondLevelLabel(domain));
71	    }
